package com.badrulamin.University_Management.service; import com.badrulamin.University_Management.exception.ResourceNotFoundException;  import com.badrulamin.University_Management.entity.FacultyAssignment; import com.badrulamin.University_Management.repository.FacultyAssignmentRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;  import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import java.util.List;  @Service @RequiredArgsConstructor @Transactional public class FacultyAssignmentService {      private final FacultyAssignmentRepository facultyAssignmentRepository;      public Page<FacultyAssignment> findAll(Pageable pageable) {         return facultyAssignmentRepository.findAll(pageable);     }      public FacultyAssignment findById(Long id) {         return facultyAssignmentRepository.findById(id)                 .orElseThrow(() -> new ResourceNotFoundException("FacultyAssignment", "id", id));     }      public FacultyAssignment save(FacultyAssignment facultyAssignment) {         return facultyAssignmentRepository.save(facultyAssignment);     }      public FacultyAssignment update(Long id, FacultyAssignment facultyAssignment) {         findById(id);         facultyAssignment.setId(id);         return facultyAssignmentRepository.save(facultyAssignment);     }      public void delete(Long id) {         findById(id);         facultyAssignmentRepository.deleteById(id);     } }